import{_ as s,o as i,c as a,a3 as t}from"./chunks/framework.DH50UWNB.js";const k=JSON.parse(`{"title":"Logs","description":"Read a Wake installation's container logs, upgrade logs and server logs, and find a request by its id in the access lines.","frontmatter":{"description":"Read a Wake installation's container logs, upgrade logs and server logs, and find a request by its id in the access lines."},"headers":[],"relativePath":"run/logs.md","filePath":"run/logs.md","lastUpdated":1794486787000}`),n={name:"run/logs.md"};function o(r,e,l,d,h,p){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;Logs&quot;">​</a></h1><h2 id="container-logs" tabindex="-1">Container logs <a class="header-anchor" href="#container-logs" aria-label="Permalink to &quot;Container logs&quot;">​</a></h2><p>Every service of an installation keeps its Docker logs in at most five files of 10 MB, so one installation&#39;s container logs stay under about 300 MB. Read them in the installation&#39;s directory:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> installation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> director</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span></span>
<span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --follow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span></span></code></pre></div><p>The services are <code>postgres</code>, <code>minio</code>, <code>server</code>, <code>web</code> and <code>caddy</code>.</p><h2 id="upgrade-logs" tabindex="-1">Upgrade logs <a class="header-anchor" href="#upgrade-logs" aria-label="Permalink to &quot;Upgrade logs&quot;">​</a></h2><p>Upgrades that run by themselves write their own logs:</p><ul><li>The server&#39;s daily upgrade: <code>auto-upgrade.log</code> in your installation directory; see <a href="/wake-dist/docs/run/upgrade#upgrade-on-a-schedule">Upgrade on a schedule</a>.</li><li>The <code>wake</code> CLI&#39;s upgrade at an agent session start: <code>auto-upgrade.log</code> in Wake&#39;s configuration directory, <code>~/.config/wake/auto-upgrade.log</code> (or <code>$XDG_CONFIG_HOME/wake/auto-upgrade.log</code>), on each machine that runs the CLI.</li></ul><h2 id="server-logs" tabindex="-1">Server logs <a class="header-anchor" href="#server-logs" aria-label="Permalink to &quot;Server logs&quot;">​</a></h2><p>The server writes one JSON object per line. Each line has <code>time</code>, <code>level</code> (<code>info</code>, <code>warn</code>, <code>error</code> or <code>fatal</code>) and <code>message</code>. Any string longer than 4,096 characters is cut there and ends with <code>… [&lt;n&gt; more characters]</code>, and newlines are escaped, so one entry is always one line.</p><p>An installation always writes <code>info</code> lines and above; its log level cannot be changed. A server you <a href="/wake-dist/docs/run/images">run yourself</a> takes <code>WAKE_LOG_LEVEL</code>, the least severe line it writes: <code>info</code> (the default), <code>warn</code> or <code>error</code>. <code>warn</code> drops the access lines and the other <code>info</code> lines; <code>fatal</code> lines are always written. See <a href="/wake-dist/docs/reference/environment#updates-and-logs">Server environment</a>.</p><h2 id="find-a-request-by-its-id" tabindex="-1">Find a request by its id <a class="header-anchor" href="#find-a-request-by-its-id" aria-label="Permalink to &quot;Find a request by its id&quot;">​</a></h2><p>Every response carries an <code>X-Request-Id</code> header such as <code>req_3k7tq2m5x4ab6cd7ef2gh3ij4k</code>, generated for that request; an <code>X-Request-Id</code> the client sends is ignored. Every line the server logs while serving the request carries the same value as <code>requestId</code>, and a <code>500</code><code>internal_error</code> response names it in its message: <code>Internal error (request id req_...)</code>. To see everything about a request someone reports, run in your installation directory:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&quot;requestId&quot;:&quot;req_3k7tq2m5x4ab6cd7ef2gh3ij4k&quot;&#39;</span></span></code></pre></div><p>Lines written outside a request, such as those of the <a href="/wake-dist/docs/reference/cleanup">cleanup</a> or the <a href="/wake-dist/docs/run/upgrade#how-you-hear-of-a-new-release">update check</a>, carry no <code>requestId</code>.</p><h2 id="access-lines" tabindex="-1">Access lines <a class="header-anchor" href="#access-lines" aria-label="Permalink to &quot;Access lines&quot;">​</a></h2><p>The server writes one <code>info</code> line with the message <code>request</code> per request, once its response is ready:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;time&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-11-02T12:00:00.000Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;requestId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;req_3k7tq2m5x4ab6cd7ef2gh3ij4k&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;level&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;info&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;request&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;method&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GET&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/v1/me&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;durationMs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>path</code> never holds the query string, and no header, cookie or body is logged.</li><li><code>durationMs</code> is the time until the response was ready. An event stream writes its line when it closes, so its <code>durationMs</code> is how long it stayed open.</li><li>A <code>GET /health</code> answered <code>200</code> is not logged, since the health checks call it every two seconds; a <code>503</code> answer is.</li></ul>`,19)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
